      const rows = LN("items")(v).map(x => x.split("|").map(y => y.trim())); const list = rows.length ? rows : c.items.map(x => [x, "[decision]"]);
      list.forEach((r, i) => { out.push(P(`**${i + 1}. ${r[0]}**`)); out.push(P(r[1] || "[decision]")); });
